<template><Teleport to="body"><section class="file-preview" role="dialog" aria-modal="true" :aria-label="doc.label" @keydown.esc="$emit('close')" @contextmenu.prevent><header><strong>{{ doc.label }}</strong><button ref="closeButton" @click="$emit('close')">Close</button></header><nav><button @click="zoom=Math.max(1,zoom-.25)">−</button><span>{{ Math.round(zoom*100) }}%</span><button @click="zoom=Math.min(3,zoom+.25)">+</button><button @click="zoom=1">Fit width</button></nav><div class="scroll"><p v-if="loading">Loading document…</p><p v-if="error" role="alert">{{ error }}</p><div ref="pages" :style="{width:zoom*100+'%'}"><img v-if="imageUrl" :src="imageUrl" :alt="doc.label" /></div></div></section></Teleport></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import {getDocument,GlobalWorkerOptions} from 'pdfjs-dist';import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';GlobalWorkerOptions.workerSrc=workerUrl
const props=defineProps({doc:Object});defineEmits(['close']);const closeButton=ref(null),pages=ref(null),zoom=ref(1),loading=ref(true),error=ref(''),imageUrl=ref('');let task,disposed=false
onMounted(async()=>{closeButton.value.focus();try{const url=new URL(props.doc.file_url,location.origin);if(!['http:','https:'].includes(url.protocol))throw Error('Unsupported document host');if(/\.(png|jpe?g|webp|gif)$/i.test(url.pathname)){imageUrl.value=url.href;return;}const response=await fetch(url,{credentials:'same-origin'});if(!response.ok)throw Error('Unavailable');const blob=await response.blob();if(blob.type.startsWith('image/'))imageUrl.value=URL.createObjectURL(blob);else{task=getDocument({data:new Uint8Array(await blob.arrayBuffer())});const pdf=await task.promise;for(let n=1;n<=pdf.numPages&&!disposed;n++){const page=await pdf.getPage(n);const view=page.getViewport({scale:2});const canvas=document.createElement('canvas');canvas.width=view.width;canvas.height=view.height;canvas.style.width='100%';pages.value.append(canvas);await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise}}}catch{if(!disposed)error.value='Could not load this document. Please close and try again.'}finally{loading.value=false}})
onBeforeUnmount(()=>{disposed=true;task?.destroy();if(imageUrl.value.startsWith('blob:'))URL.revokeObjectURL(imageUrl.value)})
</script>
<style scoped>.file-preview{position:fixed;inset:8px;z-index:20000;display:flex;flex-direction:column;overflow:hidden;background:#eef1f5;border-radius:12px}.file-preview header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;background:white}.file-preview strong{font-size:.95rem;font-weight:400}.file-preview button{min-height:40px;padding:8px 12px;background:#edf1f5;color:#a61d1d;border-radius:8px}.file-preview nav{display:flex;align-items:center;justify-content:center;gap:12px;padding:8px;background:white}.scroll{flex:1;overflow:auto;padding:12px}.scroll img{display:block;width:100%;max-width:none}.scroll :deep(canvas){display:block;margin-bottom:12px}</style>
